// coordinator: write to the N replicas for a key, succeed at W acks
async function quorumWrite(key, value, replicas, W) {
  let acks = 0;
  for (const node of replicas) {
    try {
      await node.put(key, value);   // one replica at a time
      acks++;
      if (acks >= W) return 'ok';   // stop once we have a quorum
    } catch (err) {
      // node down, try the next one
    }
  }
  return 'ok';
}
